#ifndef CSM_TRASH_H
#define CSM_TRASH_H

#include <stddef.h>
#include <time.h>

#include "inventory.h"
#include "move.h"

/* One entry of the trash: a removed session directory and what came with it. */
struct trash_entry {
	char *name;		/* the entry's directory in the trash */
	char *path;
	char *dir;		/* session directory name; NULL without metadata */
	char *origin;		/* where the session directory was */
	char *project;		/* NULL when unknown */
	char *config_dir;
	char *config_file;
	time_t removed;
	char *projects_key;	/* NULL when no projects entry came along */
	char *projects_value;	/* its raw JSON */
	unsigned long long size;	/* bytes in regular files */
};

char *trash_path(const struct move_ctx *ctx);
char *trash_entry_name(time_t when, const char *dir, unsigned n);
int trash_read(const char *trash, const char *name, struct trash_entry *e);
int trash_list(const char *trash, struct trash_entry **entries,
    size_t *count);
void trash_entry_free(struct trash_entry *e);
void trash_list_free(struct trash_entry *entries, size_t count);
void trash_remove(struct move_ctx *ctx, const struct session_dir_info *d);
void trash_restore(struct move_ctx *ctx, const char *name);
void trash_delete(struct move_ctx *ctx, const struct trash_entry *e);

#endif
